import {THREE,materials,roundedRect,rectHole,solid,yzExtrude,mesh,box} from './geometry.js';
import {portQuaternion} from '../../modeling/parts.js';
export const inputQuaternion=()=>portQuaternion('left'),outputQuaternion=()=>portQuaternion('right');
export function female3(parent,name='A093 actual3P receiving housing'){const black=materials.plastic(0x20231f,{roughness:.72}),metal=materials.metal(0xa5ad9e,{roughness:.45}),s=roundedRect(9.5,5.1,.35);for(const x of[-2.5,0,2.5])rectHole(s,x,-.2,1.65,2);const shell=mesh(parent,yzExtrude(s,8.8),black,[0,0,0],name),stop=box(parent,[9.5,.55,5.1],[0,-8.525,0],black,name+' deep stop'),latch=box(parent,[3.6,3,.55],[0,-3.5,2.8],black,name+' fixed latch'),contacts=[],tails=[];for(const x of[-2.5,0,2.5]){const r=roundedRect(1.1,1.45,.08);rectHole(r,0,0,.65,.9);contacts.push(mesh(parent,yzExtrude(r,4.5,-1.9),metal,[x,0,-.2],name+' actual hollow retained socket contact'));tails.push(box(parent,[.45,3.3,.45],[x,-8,-.2],metal,name+' actual crimp tail'));}return{shell,stop,latch,contacts,tails};}
export function male3(parent,{inserted=false,name='A093 actual3P male'}={}){const g=new THREE.Group();if(inserted)g.rotation.z=Math.PI;parent.add(g);const black=materials.plastic(0x20231f,{roughness:.72}),metal=materials.metal(0xa7ad9f,{roughness:.43}),rear=box(g,[11.1,7.5,6.45],[0,-5.25,0],black,name+' retained rear'),walls=[];for(const x of[-5.2,5.2])walls.push(box(g,[.7,7,6.45],[x,-.5,0],black,name+' outside receiving-housing guard'));const floor=box(g,[9.7,7,.55],[0,-.5,-2.95],black,name+' real floor outside receiving-housing bottom'),latch=box(g,[2.8,3,.6],[0,-2.5,3.5],black,name+' actual latch ramp'),contacts=[],tails=[];for(const x of[-2.5,0,2.5]){contacts.push(box(g,[.52,7.5,.52],[x,-.5,-.2],metal,name+' retained exposed mating pin'));tails.push(box(g,[.52,3.6,.52],[x,-10,-.2],metal,name+' crimp tail'));}return{frame:g,rear,walls,floor,latch,contacts,tails};}
export function grovePlug(parent){const white=materials.plastic(0xe8e8df,{roughness:.65}),metal=materials.metal(0xb4ad8d,{roughness:.4}),s=roundedRect(8.4,2.9,.24);for(const x of[-3,-1,1,3])rectHole(s,x,-.2,.74,.9);const nose=mesh(parent,yzExtrude(s,3.8,2.6),white,[0,0,0],'A093 supplied actual male4-position Grove plug with four real chambers'),retainer=box(parent,[8.4,1.6,2.9],[0,3.4,0],white,'A093 Grove wire retainer'),latch=box(parent,[3.8,1.8,.46],[0,1.4,1.6],white,'A093 Grove male plug retaining tongue'),contacts=[],returns=[];for(const x of[-3,-1,1]){contacts.push(box(parent,[.6,1.5,.12],[x,.1,-.59],metal,'A093 actual one of3 Grove crimp contacts;NC chamber empty'));returns.push(box(parent,[.42,3,.42],[x,2.75,-.1],metal,'A093 actual retained Grove conductor tail'));}return{nose,retainer,latch,contacts,returns,populatedPositions:[0,1,2],emptyPosition:3};}
